INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(6301, 'Judges 9:16', 'Judges', 9, 16, '&nbsp;نو يوتام خپله خبره جارى وساتله چې، ”کله تاسو ابى‌مَلِک بادشاه جوړ کړو نو تاسو په رښتيا مخلِصه او رښتونى وئ څۀ؟ تاسو د جدعون د ياد څۀ درناوى وکړو او د هغۀ د خاندان سره مو ښۀ سلوک وکړو څۀ لکه څنګه چې د هغۀ د کارونو حق جوړيږى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6302, 'Judges 9:17', 'Judges', 9, 17, '&nbsp;هغه راپه ياد کړئ چې زما پلار ستاسو دپاره جنګ وکړو. هغۀ خپل ژوند په خطره کښې واچولو چې تاسو د ميديانيانو نه بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6303, 'Judges 9:18', 'Judges', 9, 18, '&nbsp;خو نن تاسو زما د پلار د خاندان خِلاف شوئ. تاسو د هغۀ زامن اويا سړى د يو کاڼى دپاسه ووژل او دا ځکه چې د هغۀ د وينځې زوئ ابى‌مَلِک ستاسو رشته‌دار دے او تاسو هغه د شِکم بادشاه جوړ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6304, 'Judges 9:19', 'Judges', 9, 19, '&nbsp;کۀ تاسو نن د جدعون او د هغۀ اولاد سره د عزت او ښۀ ايمان سلوک وکړو، نو تاسو دې د ابى‌مَلِک نه خوشحاله شئ او هغه دې ستاسو نه خوشحاله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6305, 'Judges 9:20', 'Judges', 9, 20, '&nbsp;خو کۀ داسې نۀ وى نو ابى‌مَلِک ته دې اور بل شى او د شِکم او بيت‌مِلو خلق دې وسوزوى. د شِکم او بيت‌مِلو د خلقو نه دې اور بل شى او ابى‌مَلِک دې وسوزوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6306, 'Judges 9:21', 'Judges', 9, 21, '&nbsp;يوتام د خپل ورور ابى‌مَلِک نه يرېدو نو ځکه هغه وتښتېدو او بير ته د اوسېدو دپاره لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6307, 'Judges 9:22', 'Judges', 9, 22, '&nbsp;ابى‌مَلِک په بنى اِسرائيلو باندې درې کاله بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6308, 'Judges 9:23', 'Judges', 9, 23, '&nbsp;بيا خُدائ پاک د ابى‌مَلِک او د شِکم د خلقو په مينځ کښې دشمنى پېدا کړه او هغوئ د ابى‌مَلِک خِلاف بغاوت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6309, 'Judges 9:24', 'Judges', 9, 24, '&nbsp;داسې د دې دپاره وشول چې ابى‌مَلِک او د شِکم خلقو ته د خپلو بدو سزا مِلاو شى چا چې د هغۀ مدد کړے وو چې د جدعون اويا زامن ووژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6310, 'Judges 9:25', 'Judges', 9, 25, '&nbsp;د شِکم خلقو د ابى‌مَلِک خِلاف د غرونو په سرونو باندې په پټ ځائ کښې سړى کښېنول او هر څوک هم چې په هغه لاره تېرېدل نو هغوئ به يې لوټ کول. نو ابى‌مَلِک د دې نه خبر شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6311, 'Judges 9:26', 'Judges', 9, 26, '&nbsp;د عبيد زوئ جعل د خپلو وروڼو سره شِکم ته راغلو او د هغه ځائ خلقو په هغۀ باندې اعتبار وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6312, 'Judges 9:27', 'Judges', 9, 27, '&nbsp;هغوئ ټول خپلو د انګورو باغونو ته دننه لاړل او انګور يې راوشوکول او مے يې ترې نه جوړ کړل او يوه مېله يې جوړه کړه. هغوئ د خپل خُدائ د عبادت ځائ ته لاړل، چرته چې هغوئ خوراک څښاک وکړو او ابى‌مَلِک ته يې کنځل وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6313, 'Judges 9:28', 'Judges', 9, 28, '&nbsp;د عبيد زوئ جعل ووئيل، ”دا په شِکم کښې مونږ څۀ قِسم سړى يُو؟ مونږ د ابى‌مَلِک خِدمت ولې کوُو؟ هغۀ دے څوک؟ هغه د جدعون زوئ دے. او زبول ته د هغۀ نه حُکم ملاويږى، خو مونږ ولې د هغۀ خِدمت وکړُو؟ د خپل پلار نيکۀ همور وفادار اوسئ، چا چې ستاسو د قبيلې بنياد اېښے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6314, 'Judges 9:29', 'Judges', 9, 29, '&nbsp;زما دا ارمان دے چې زۀ د دې خلقو مشر وے نو ما به د ابى‌مَلِک نه ځان خلاص کړے وے. ما به هغۀ ته وئيلى وے چې خپل لښکر تيار کړه او بهر د جنګ دپاره راووځه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6315, 'Judges 9:30', 'Judges', 9, 30, '&nbsp;د هغه ښار حکمران زبول چې کله هغه څۀ واورېدل چې جعل وئيلى وُو نو په غصه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6316, 'Judges 9:31', 'Judges', 9, 31, '&nbsp;هغۀ په ارومه کښې ابى‌مَلِک ته پېغام وړُونکى ولېږل چې داسې ورته ووائى، ”د عبيد زوئ جعل او د هغۀ وروڼه شِکم ته راغلى دى او هغوئ د ښار خلق لمسوى چې ستا خِلاف بغاوت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6317, 'Judges 9:32', 'Judges', 9, 32, '&nbsp;نو اوس، تا او ستا خلقو له په کار دى چې لاړ شئ او په پټو کښې پټ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6318, 'Judges 9:33', 'Judges', 9, 33, '&nbsp;سبا سحر چې څنګه نمر راوخېژى نو تاسو پاڅئ او په ښار باندې ناڅاپه حمله وکړئ. نو چې کله جعل او د هغۀ سړى ستاسو خِلاف راوځى، نو چې څۀ مو خوښه وى هغه ورسره وکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6319, 'Judges 9:34', 'Judges', 9, 34, '&nbsp;نو ابى‌مَلِک او د هغۀ ټول سړى د شپې لاړل او د شِکم نه بهر په څلورو ډلو کښې پټ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6320, 'Judges 9:35', 'Judges', 9, 35, '&nbsp;نو د عبيد زوئ جعل بهر تلے وو او د ښار د دروازې په خولۀ کښې ولاړ وو او هم په هغه وخت ابى‌مَلِک د خپلو فوجيانو سره د پټو ځايونو نه راووتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6321, 'Judges 9:36', 'Judges', 9, 36, '&nbsp;جعل هغوئ وليدل او زبول ته يې ووئيل، ”ګوره، د غرونو د سرونو نه سړى راروان دى.“ زبول جواب ورکړو، ”هغه سړى نۀ دى. هغه صرف د غرونو سورى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6322, 'Judges 9:37', 'Judges', 9, 37, '&nbsp;جعل ورته بيا ووئيل، ”ګوره، د غرۀ د سر نه سړى راکوزيږى او يوه ډله د قسمت ښودونکى څېړۍ د ونې نه په لار راروانه ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6323, 'Judges 9:38', 'Judges', 9, 38, '&nbsp;بيا زبول هغۀ ته ووئيل، ”اوس ستا لافې چرته دى؟ تۀ هم هغه کس وې چې تا وئيل چې مونږ د دې سړى ابى‌مَلِک خِدمت ولې وکړُو. دا هغه سړى دى چې تا ورسره د نفرت سلوک کولو. اوس لاړ شه او جنګ ورسره وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6324, 'Judges 9:39', 'Judges', 9, 39, '&nbsp;جعل د شِکم خلق بوتلل او د ابى‌مَلِک سره يې جنګ وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6325, 'Judges 9:40', 'Judges', 9, 40, '&nbsp;جعل وتښتېدو او ابى‌مَلِک ورپسې وو. د ښار د دروازې نه د ننوتلو نه مخکښې ډېر کسان زخميان شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6326, 'Judges 9:41', 'Judges', 9, 41, '&nbsp;ابى‌مَلِک په ارومه کښې اوسېدو او زبول د شِکم نه جعل او د هغۀ وروڼه وشړل، نور هلته نۀ شول اوسېدلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6327, 'Judges 9:42', 'Judges', 9, 42, '&nbsp;په ورپسې ورځ ابى‌مَلِک ته پته ولګېده چې د شِکم خلق پټو ته راووتل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6328, 'Judges 9:43', 'Judges', 9, 43, '&nbsp;نو هغۀ خپل سړى بوتلل، په درېو ډلو کښې يې تقسيم کړل، په پټو کښې پټ شول او اِنتظار يې کولو. کله چې هغۀ وليدل چې خلق د ښار نه بهر روان دى، نو هغه د پټ ځائ نه د هغوئ د وژلو دپاره راووتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6329, 'Judges 9:44', 'Judges', 9, 44, '&nbsp;کله چې ابى‌مَلِک او د هغۀ قبيله په تېزۍ سره د ښار د دروازې د حِفاظت دپاره مخکښې شوه، نو هغه دوو نورو ډلو په پټو کښې په خلقو باندې حمله وکړه او ټول يې ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6330, 'Judges 9:45', 'Judges', 9, 45, '&nbsp;ټوله ورځ جنګ جارى وو. ابى‌مَلِک ښار قبضه کړو، د هغې خلق يې ووژل، ښار يې وران کړو او زمکه يې په مالګه پټه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6331, 'Judges 9:46', 'Judges', 9, 46, '&nbsp;کله چې د شِکم په قلعه کښې ټول مشران سړى د دې نه خبر شول، نو هغوئ د بعل‌بريت د لوظ عبادتخانې په مضبوط ځائ کښې پناه ولټوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6332, 'Judges 9:47', 'Judges', 9, 47, '&nbsp;ابى‌مَلِک خبر شو چې هغوئ هلته راغونډ شوى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6333, 'Judges 9:48', 'Judges', 9, 48, '&nbsp;نو هغه د خپلو سړو سره د ضلمون غر ته وختلو. هلته هغۀ يو تبر واخستلو، د ونې څانګه يې ماته کړه او په خپله اوږه يې کېښوده. هغۀ خپلو سړو ته ووئيل چې، ”زر شئ او هم دغه شان وکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6334, 'Judges 9:49', 'Judges', 9, 49, '&nbsp;نو هر يو سړى د ونې څۀ څانګې ماتې کړې، بيا هغوئ ابى‌مَلِک پسې لاړل او لرګى يې د قلعې دېوالونو سره ډېرے کړل. هغوئ په دې باندې اور بَل کړو، هغه دننه خلق د نورو ټولو خلقو سره مړۀ شول چې په قلعه کښې وُو. دا تقريباً زر سړى او ښځې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6335, 'Judges 9:50', 'Judges', 9, 50, '&nbsp;ابى‌مَلِک تيبض ته لاړو، د ښار نه يې ګېره واچوله او قبضه يې کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6336, 'Judges 9:51', 'Judges', 9, 51, '&nbsp;هلته يو مضبوط برج وو او په ښار کښې هر يو سړى او ښځې، سره د مشرانو هغې ته ورمنډه کړه. خپل ځانونه يې په کښې بند کړل او پاس چت ته وختل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6337, 'Judges 9:52', 'Judges', 9, 52, '&nbsp;کله چې ابى‌مَلِک په برج باندې حمله کولو له راغلو، نو هغه دروازې ته ورَغلو چې په برج باندې اور بَل کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6338, 'Judges 9:53', 'Judges', 9, 53, '&nbsp;خو يوې ښځې د هغۀ په سر باندې د بره نه د ژرندې پل وروغورزولو او د هغۀ کوپړۍ يې ماته کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6339, 'Judges 9:54', 'Judges', 9, 54, '&nbsp;نو هغۀ زر هغه زلمے راوغوښتلو کوم چې د هغۀ وسله وړله او حُکم يې ورکړو، ”خپله تُوره راوباسه او ما ووژنه. زۀ دا نۀ غواړم چې څوک ووائى چې زۀ يوې ښځې وژلے يم.“ نو هغه زلمى ترې نه تُوره په بل طرف وويستله او هغه مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6340, 'Judges 9:55', 'Judges', 9, 55, '&nbsp;کله چې بنى اِسرائيلو وليدل چې ابى‌مَلِک مړ شو، نو هغوئ ټول کور ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6341, 'Judges 9:56', 'Judges', 9, 56, '&nbsp;نو داسې خُدائ پاک ابى‌مَلِک له د هغو بدو بدله ورکړه کوم بد چې هغۀ د خپل پلار خِلاف کړى وُو چې اويا وروڼه يې وژلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6342, 'Judges 9:57', 'Judges', 9, 57, '&nbsp;خُدائ پاک د شِکم خلقو له هم د هغوئ د بدمعاشۍ په وجه سخته سزا ورکړه، څنګه چې د جدعون زوئ يوتام وئيلى وُو چې په هغوئ به داسې کيږى چې کله هغۀ پرې لعنت وئيلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6343, 'Judges 10:1', 'Judges', 10, 1, '&nbsp;د ابى‌مَلِک د مرګ نه پس د دودو نمسے او د فُوه زوئ، تولع د بنى اِسرائيلو د بچ کولو دپاره راغلو. هغه د يساکار د قبيلې نه وو او د اِفرائيم د غرونو په مُلک سمير کښې اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6344, 'Judges 10:2', 'Judges', 10, 2, '&nbsp;هغه درويشت کاله د بنى اِسرائيلو قاضى وو. بيا هغه مړ شو او په سمير کښې ښخ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6345, 'Judges 10:3', 'Judges', 10, 3, '&nbsp;د تولع نه پس يائير د جِلعاد نه راغلو. هغه دوويشت کاله د بنى اِسرائيلو قاضى وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6346, 'Judges 10:4', 'Judges', 10, 4, '&nbsp;د هغۀ دېرش زامن وُو چا چې په دېرشو خرونو سورلى کړې وه. د جِلعاد په مُلک کښې د هغوئ دېرش ښارونه وُو، چې تر اوسه پورې د يائير په نوم ياديږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6347, 'Judges 10:5', 'Judges', 10, 5, '&nbsp;يائير مړ شو او په قامون کښې ښخ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6348, 'Judges 10:6', 'Judges', 10, 6, '&nbsp;بنى اِسرائيلو يو ځل بيا د مالِک خُدائ خِلاف ګناه وکړه او د بعل او عستارات او هم داسې د شام، د صيدا، د موآب، د عمون او د فلستيانو د معبودانو عبادت يې وکړو. هغوئ مالِک خُدائ پرېښودو او د هغۀ عبادت کول يې بس کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6349, 'Judges 10:7', 'Judges', 10, 7, '&nbsp;نو مالِک خُدائ بنى اِسرائيلو ته په قهر شو او فلستيانو او عمونيانو له يې موقع ورکړه چې بنى اِسرائيلو له شکست ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6350, 'Judges 10:8', 'Judges', 10, 8, '&nbsp;هغوئ اتلس کاله هغه ټول بنى اِسرائيل په تکليف کښې واچول او ظلم زياتے يې ورسره کولو کوم چې په جِلعاد کښې د اُردن سيند نمرخاتۀ طرف ته د اموريانو په مُلک کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6351, 'Judges 10:9', 'Judges', 10, 9, '&nbsp;عمونيان د اُردن نه هم پورې وتل چې د يهوداه، بنيامين او اِفرائيم قبيلو سره جنګ وکړى. بنى اِسرائيليان په سخت کړاؤ کښې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6352, 'Judges 10:10', 'Judges', 10, 10, '&nbsp;نو بنى اِسرائيلو مالِک خُدائ ته فرياد وکړو او وې وئيل، ”مونږ ستا خِلاف ګناه کړې ده، ځکه چې مونږ تۀ، زمونږ خپل خُدائ پاک پرېښودې او د بعل د بُتانو عبادت مو وکړو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6353, 'Judges 10:11', 'Judges', 10, 11, '&nbsp;مالِک خُدائ هغوئ له دا جواب ورکړو، ”مِصريانو، اموريانو، عمونيانو، فلستيانو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6354, 'Judges 10:12', 'Judges', 10, 12, '&nbsp;صيدانيانو، عماليقيانو او ماعونيانو په تېره زمانه کښې تاسو سره ظلم زياتے کولو او تاسو ما ته فرياد وکړو. ما تاسو د هغوئ نه بچ نۀ کړئ څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6355, 'Judges 10:13', 'Judges', 10, 13, '&nbsp;خو تاسو بيا هم زۀ پرېښودم او د نورو معبودانو عبادت مو وکړو، نو زۀ به بيا تاسو نۀ بچ کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6356, 'Judges 10:14', 'Judges', 10, 14, '&nbsp;لاړ شئ او هغه معبودانو ته فرياد وکړئ چې تاسو خوښ کړى دى. کله چې تاسو په تکليف کښې يئ نو هغوئ له موقع ورکړئ چې تاسو بچ کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6357, 'Judges 10:15', 'Judges', 10, 15, '&nbsp;خو بنى اِسرائيلو مالِک خُدائ ته ووئيل، ”مونږ ګناه کړې ده. څۀ چې ستا خوښه وى نو هغه راسره وکړه، خو نن مونږ بچ کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6358, 'Judges 10:16', 'Judges', 10, 16, '&nbsp;نو هغوئ د پردو معبودانو نه ځان خلاص کړو او د مالِک خُدائ عبادت يې وکړو، نو د بنى اِسرائيلو په تکليف باندې د هغۀ زړۀ وسوزېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6359, 'Judges 10:17', 'Judges', 10, 17, '&nbsp;بيا د عمونيانو لښکر د جنګ دپاره تيارے وکړو او په جِلعاد کښې يې خېمې ولګولې. بنى اِسرائيل هم راغونډ شول او په مصفاه کښې يې خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6360, 'Judges 10:18', 'Judges', 10, 18, '&nbsp;هلته خلقو او د بنى اِسرائيلو د قبيلو مشرانو يو بل ته ووئيل، ”څوک چې په عمونيانو باندې وړومبے حمله وکړى نو هغه به د جِلعاد په ټولو خلقو باندې مشر شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6361, 'Judges 11:1', 'Judges', 11, 1, '&nbsp;د جِلعاد يو بهادر فوجى اِفتاح د يوې کنجرې زوئ وو. د هغۀ د پلار هم جِلعاد نوم وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6362, 'Judges 11:2', 'Judges', 11, 2, '&nbsp;د جِلعاد د خپلې ښځې نه نور زامن هم وُو او کله چې هغوئ لوئ شول، نو اِفتاح يې مجبور کړو چې د کور نه لاړ شى. هغوئ هغۀ ته ووئيل، ”تا ته به زمونږ د پلار په ميراث کښې هيڅ هم نۀ ملاويږى، تۀ د بلې ښځې زوئ يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6363, 'Judges 11:3', 'Judges', 11, 3, '&nbsp;اِفتاح د خپلو وروڼو نه وتښتېدو او د طوب په مُلک کښې اوسېدو. هلته د بې‌کاره بدمعاشانو ډله د هغۀ سره شوه او هغوئ به د هغۀ سره ګرځېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6364, 'Judges 11:4', 'Judges', 11, 4, '&nbsp;لږه موده پس عمونيان د بنى اِسرائيلو خِلاف جنګ له لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6365, 'Judges 11:5', 'Judges', 11, 5, '&nbsp;کله چې داسې وشول نو د جِلعاد مشران لاړل چې اِفتاح د طوب مُلک نه واپس راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6366, 'Judges 11:6', 'Judges', 11, 6, '&nbsp;هغوئ ووئيل، ”راشه او د عمونيانو خلاف په جنګ کښې زمونږ مشر شه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6367, 'Judges 11:7', 'Judges', 11, 7, '&nbsp;خو اِفتاح ورته ووئيل، ”تاسو زما نه دومره نفرت وکړو چې دې ته مو مجبور کړم چې د خپل پلار د کور نه لاړ شم. اوس چې تاسو په تکليف کښې يئ نو ما له ولې راغلى يئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6368, 'Judges 11:8', 'Judges', 11, 8, '&nbsp;هغوئ اِفتاح ته ووئيل، ”اوس مونږ تا له ځکه راواپس شُو چې غواړُو چې مونږ سره لاړ شې او د عمونيانو سره جنګ وکړې او د جِلعاد د ټولو خلقو مشرى وکړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6369, 'Judges 11:9', 'Judges', 11, 9, '&nbsp;اِفتاح هغوئ ته ووئيل، ”ښه ټيک ده کۀ تاسو ما د ځان سره واپس بوځئ چې عمونيانو سره جنګ وکړم او مالِک خُدائ ما له فتح راکړى، نو زۀ به ستاسو مشر شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6370, 'Judges 11:10', 'Judges', 11, 10, '&nbsp;هغوئ ورته په جواب کښې ووئيل، ”مونږ ته منظوره ده. مالِک خُدائ زمونږ ګواه دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6371, 'Judges 11:11', 'Judges', 11, 11, '&nbsp;نو اِفتاح د جِلعاد مشرانو سره لاړو او خلقو هغه د قبيلو مشر او فوجى مشر جوړ کړو. اِفتاح په مصفاه کښې د مالِک خُدائ په وړاندې خپل د تړون خبرې بيان کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6372, 'Judges 11:12', 'Judges', 11, 12, '&nbsp;بيا اِفتاح د عمون بادشاه له پېغام وړُونکى ولېږل چې ورته ووائى، ”تۀ زمونږ سره څۀ لانجه لرې؟ تا زمونږ په مُلک باندې ولې حمله کړې ده؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6373, 'Judges 11:13', 'Judges', 11, 13, '&nbsp;د عمون بادشاه د اِفتاح پېغام وړونکو ته جواب ورکړو، ”کله چې بنى اِسرائيليان د مِصر نه راووتل، نو هغوئ د ارنون سيند نه واخله تر يبوق سيند او د اُردن سيند پورې زما مُلک ونيولو. نو اوس به تۀ ما له دا بغېر د جنګ جګړې واپس راکوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6374, 'Judges 11:14', 'Judges', 11, 14, '&nbsp;اِفتاح د عمون بادشاه ته واپس پېغام وړُونکى ولېږل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6375, 'Judges 11:15', 'Judges', 11, 15, '&nbsp;چې داسې ورته ووائى، ”دا رښتيا نۀ دى چې بنى اِسرائيلو د موآب يا د عمون مُلک نيولے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6376, 'Judges 11:16', 'Judges', 11, 16, '&nbsp;داسې وشول يعنې کله چې بنى اِسرائيليان د مِصر نه لاړل، نو هغوئ د صحرا په لاره بحرِقُلزم ته روان شول او قادِس ته راغلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6377, 'Judges 11:17', 'Judges', 11, 17, '&nbsp;بيا هغوئ د ادوم بادشاه له پېغام وړُونکى ولېږل چې اجازت ترې نه وغواړى چې د هغۀ په مُلک کښې تېر شى. خو د ادوم بادشاه هغوئ نۀ پرېښودل. هغوئ د موآب بادشاه ته هم ووئيل، خو هغۀ هم پرې نۀ ښودل چې د هغۀ په مُلک کښې تېر شى. نو بنى اِسرائيليان په قادِس کښې ايسار شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6378, 'Judges 11:18', 'Judges', 11, 18, '&nbsp;بيا هغوئ په صحرا کښې روان وُو، د ادوم او د موآب مُلک نه تاوېدل تر دې پورې چې د موآب نمرخاتۀ طرف ته راغلل چې د ارنون سيند بل طرف ته وو. هغوئ هلته خېمې ولګولې، خو هغوئ د ارنون نه پورې نۀ وتل ځکه چې دا د موآب د حد پوله وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6379, 'Judges 11:19', 'Judges', 11, 19, '&nbsp;بيا بنى اِسرائيلو په حسبون کښې د اموريانو بادشاه سيحون ته پېغام وړُونکى ولېږل، چې د هغۀ نه اجازت وغواړى چې هغوئ د هغۀ په مُلک کښې تېر شى او خپل مُلک ته لاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6380, 'Judges 11:20', 'Judges', 11, 20, '&nbsp;خو سيحون بنى اِسرائيليان تېرېدو ته نۀ پرېښودل ځکه چې په هغوئ بې‌اعتباره وو. هغۀ خپل ټول لښکر راغونډ کړو، په يهض کښې يې خېمې ولګولې او په بنى اِسرائيلو يې حمله وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6381, 'Judges 11:21', 'Judges', 11, 21, '&nbsp;خو مالِک خُدائ د بنى اِسرائيلو خُدائ پاک، بنى اِسرائيلو له په سيحون او د هغۀ په لښکر باندې فتح ورکړه. نو بنى اِسرائيلو د هغه اموريانو هغه ټوله علاقه قبضه کړه کوم چې په هغه مُلک کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6382, 'Judges 11:22', 'Judges', 11, 22, '&nbsp;هغوئ په جنوب کښې د ارنون نه واخله په شمال کښې تر يبوق پورې او نمرخاتۀ طرف ته د صحرا نه واخله نمرپرېواتۀ طرف ته د اُردن سيند پورې د اموريانو ټوله علاقه قبضه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6383, 'Judges 11:23', 'Judges', 11, 23, '&nbsp;نو دا مالِک خُدائ د بنى اِسرائيلو خُدائ پاک وو چا چې د خپلو خلقو بنى اِسرائيلو دپاره اموريان وشړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6384, 'Judges 11:24', 'Judges', 11, 24, '&nbsp;چې تاسو له څۀ هم ستاسو معبود کموس درکړى دى نو هغه به ستاسو سره وى. خو چې مالِک خُدائ، زمونږ خُدائ پاک مونږ له څۀ هم راکړى دى هغه به زمونږ سره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6385, 'Judges 11:25', 'Judges', 11, 25, '&nbsp;ستاسو خيال دا دے څۀ چې تاسو د موآب د بادشاه د صفور د زوئ بلق نه ښۀ يئ؟ هغۀ کله بنى اِسرائيلو ته د جنګ دعوت ورکړے دے څۀ؟ هغۀ کله زمونږ خِلاف جنګ کړے دے څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6386, 'Judges 11:26', 'Judges', 11, 26, '&nbsp;بنى اِسرائيلو درې سوه کالو راسې حسبون او عيروعير او د دې نه ګېرچاپېره ښارونه او د ارنون سيند په غاړه ټول ښارونه قبضه کړى دى. تاسو په هغه وخت هغه واپس ولې نۀ وُو نيولى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6387, 'Judges 11:27', 'Judges', 11, 27, '&nbsp;نه، ما ستاسو سره هيڅ بد نۀ دى کړى. تاسو دا بد کوئ چې زما سره جنګ کوئ. مالِک خُدائ قاضى دے. هغه به نن د بنى اِسرائيلو او عمونيانو په مينځ کښې فېصله وکړى چې څوک په حقه دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6388, 'Judges 11:28', 'Judges', 11, 28, '&nbsp;خو د عمون بادشاه، د اِفتاح د طرف نه دې پېغام ته هيڅ پام ونۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6389, 'Judges 11:29', 'Judges', 11, 29, '&nbsp;بيا د مالِک خُدائ روح په اِفتاح نازل شو. هغه په جِلعاد او په منسى کښې تېر شو او په جِلعاد کښې مصفاه ته راواپس شو او د هغه ځائ نه يې د عمونيانو خِلاف روان شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6390, 'Judges 11:30', 'Judges', 11, 30, '&nbsp;اِفتاح د مالِک خُدائ دپاره دا منښته ومنله، ”کۀ تۀ ما له په عمونيانو باندې فتح راکړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6391, 'Judges 11:31', 'Judges', 11, 31, '&nbsp;کۀ زۀ واپس په خېر سره راورسېدم او څوک هم چې زما د کور نه وړومبے زما سره د مِلاوېدو دپاره راووتل نو هغه به د مالِک خُدائ وى نو هغه څيز به هغۀ ته د سوزېدونکې نذرانې په توګه پېش کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6392, 'Judges 11:32', 'Judges', 11, 32, '&nbsp;نو اِفتاح د عمونيانو سره جنګ دپاره د سيند نه پورې وتلو او مالِک خُدائ هغۀ له فتح ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6393, 'Judges 11:33', 'Judges', 11, 33, '&nbsp;هغۀ د عيروعير نه واخله، د مِنيت نه ګېرچاپېره علاقه او تر ابيل کراميم پورې ټول شل ښارونه وران کړل. هلته يو لوئ قتلِ عام وو او عمونيانو د بنى اِسرائيلو نه شکست وخوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6394, 'Judges 11:34', 'Judges', 11, 34, '&nbsp;کله چې اِفتاح واپس په مصفاه کښې کور ته لاړو، هلته د هغۀ لور د هغۀ سره مِلاوېدو له راروانه وه، ګډېده او تمبل يې وهلو. هغه يې اېک يوه لور وه، د هغۀ نور زامن او لوڼه نۀ وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6395, 'Judges 11:35', 'Judges', 11, 35, '&nbsp;کله يې چې هغه وليده، نو هغۀ د خفګان نه خپلې جامې وشلولې او وې وئيل، ”اے زما لورې، زۀ خو به تباه او برباد شم. ما چې د مالِک خُدائ سره کوم لوظ کړے دے، زۀ خو هغه نۀ شم ماتولے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6396, 'Judges 11:36', 'Judges', 11, 36, '&nbsp;هغې ورته ووئيل، ”کۀ تا د مالِک خُدائ سره وعده کړې وى نو تا چې څۀ وئيلى دى نو هم هغه شان ما سره وکړه، ځکه چې مالِک خُدائ ستا دشمنانو عمونيانو نه بدل واخستلو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6397, 'Judges 11:37', 'Judges', 11, 37, '&nbsp;خو هغې خپل پلار ته ووئيل، ”تۀ زما دپاره دا يو کار وکړه، دوه مياشتې ما يواځې پرېږده، چې زۀ د خپلو ملګرو سره د غرونو په علاقه کښې سرګردانه وګرځم او ماتم وکړم ځکه چې زۀ په پېغلتوب کښې مړه کېږم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6398, 'Judges 11:38', 'Judges', 11, 38, '&nbsp;هغۀ ورته ووئيل چې، ”لاړه شه،“ او دؤو مياشتو له يې لرې ولېږله. هغه د خپلو ملګرو سره د غرونو علاقې ته لاړه او ماتم يې وکړو ځکه چې هغه بې‌اولاده او بې‌وادۀ مړه کېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6399, 'Judges 11:39', 'Judges', 11, 39, '&nbsp;دوه مياشتې پس هغه واپس خپل پلار له راغله. هغۀ هم هغه شان وکړل چې څنګه يې د مالِک خُدائ سره لوظ کړے وو. او هغه په پېغلتوب کښې مړه شوه او د يو سړى سره يې هم تعلق نۀ وو لرلے نو داسې په بنى اِسرائيلو کښې د دې نه يو رِواج جوړ شو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6400, 'Judges 11:40', 'Judges', 11, 40, '&nbsp;چې ښځې به هر کال څلور ورځې تلې چې د جِلعاد د اِفتاح د لور دپاره ماتم وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');